import subprocess
import os

def get_ls_result(dir_path: str) -> str:
    try:
        # Sanitize the directory path to prevent command injection
        sanitized_path = os.path.realpath(dir_path)

        if not os.path.isdir(sanitized_path):
            return ""

        result = subprocess.run(['ls', '-l', sanitized_path], capture_output=True, text=True)

        if result.returncode == 0:
            return result.stdout
        else:
            return ""
    except Exception:
        return ""

